const { chromium } = require('$PW');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  await p.goto('file://$PWD/index.html');
  const add = async (t, pr) => { await p.fill('[data-testid=todo-input]', t); await p.selectOption('[data-testid=todo-priority]', pr); await p.click('[data-testid=todo-add]'); };
  await add('L1','low'); await add('M1','med'); await add('H1','high'); await add('L2','low'); await add('H2','high'); await add('M2','med');
  const texts = () => p.\$\$eval('[data-testid=todo-text]', e => e.map(x => x.textContent).join(' '));
  console.log('added:     ', await texts());
  await p.locator('[data-testid=todo-item]', { hasText: 'H1' }).locator('[data-testid=todo-toggle]').check();
  console.log('H1 done:   ', await texts());
  await p.locator('[data-testid=todo-item]', { hasText: 'L1' }).locator('[data-testid=todo-toggle]').check();
  console.log('L1 done:   ', await texts());
  await p.locator('[data-testid=todo-item]', { hasText: 'H1' }).locator('[data-testid=todo-toggle]').uncheck();
  console.log('H1 undone: ', await texts());
  await p.reload(); console.log('reload:    ', await texts());
  await b.close();
})();
EOF
node $SP/t.js

